class Solution {
public:
    int maximumLength(vector<int>& nums) {
        unordered_map<long long, int> cnt;
        cnt.reserve(nums.size() * 2);
        for (int v : nums) cnt[v]++;
        int best = 0;
        for (auto& p : cnt) {
            long long x = p.first;
            if (x == 1) continue;
            long long cur = x;
            int len = 0;
            while (cnt.count(cur) && cnt[cur] >= 2) {
                len += 2;
                cur = cur * cur;
                if (cur > 1000000000LL) break;
            }
            if (cur <= 1000000000LL && cnt.count(cur) && cnt[cur] >= 1) {
                best = max(best, len + 1);
            } else if (len > 0) {
                best = max(best, len - 1);
            }
        }
        int ones = cnt.count(1) ? cnt[1] : 0;
        if (ones > 0) best = max(best, ones % 2 == 1 ? ones : ones - 1);
        return max(best, 1);
    }
};
